<?php
$base='../';$tituloPagina='Pedidos';require_once __DIR__.'/../php/conexion.php';require_once __DIR__.'/../php/auth.php';require_once __DIR__.'/../php/util.php';requerirAdministrador();
$estadosPermitidos=['pendiente','en_preparacion','listo','entregado'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id_venta']??0); $estado=$_POST['estado']??''; if($id && in_array($estado,$estadosPermitidos,true)){ $actualizar=$conexion->prepare('UPDATE ventas SET estado=? WHERE id_venta=?'); $actualizar->bind_param('si',$estado,$id); $actualizar->execute(); mensaje('success','Estado del pedido actualizado.'); } header('Location: ventas.php'); exit; }
$ventas=$conexion->query("SELECT v.id_venta,v.fecha,v.total,v.estado,v.tipo_entrega,v.direccion_entrega,v.fecha_entrega,v.notas,u.nombre,u.correo,GROUP_CONCAT(CONCAT(d.cantidad,' x ',p.nombre_producto) SEPARATOR ' · ') productos FROM ventas v JOIN usuarios u ON u.id_usuario=v.id_usuario JOIN detalle_venta d ON d.id_venta=v.id_venta JOIN productos p ON p.id_producto=d.id_producto GROUP BY v.id_venta,v.fecha,v.total,v.estado,v.tipo_entrega,v.direccion_entrega,v.fecha_entrega,v.notas,u.nombre,u.correo ORDER BY v.fecha DESC");require_once __DIR__.'/../php/encabezado.php';
?><main class="container py-5"><p class="eyebrow">PEDIDOS</p><h1>Gestionar pedidos</h1><?php mostrarMensaje(); ?><p class="lead">Actualiza el estado y revisa cómo cada cliente recibirá su compra.</p><div class="table-responsive mt-4"><table class="table table-hover align-middle"><thead><tr><th>Pedido</th><th>Cliente</th><th>Entrega</th><th>Detalle</th><th>Estado</th><th>Total</th></tr></thead><tbody><?php while($v=$ventas->fetch_assoc()): ?><tr><td><strong>#<?php echo $v['id_venta']; ?></strong><br><small><?php echo e($v['fecha']); ?></small></td><td><?php echo e($v['nombre']); ?><br><small><?php echo e($v['correo']); ?></small></td><td><?php echo $v['tipo_entrega']==='delivery'?'A domicilio':'Retiro'; ?><?php if($v['direccion_entrega']): ?><br><small><?php echo e($v['direccion_entrega']); ?></small><?php endif; ?><?php if($v['fecha_entrega']): ?><br><small><?php echo e($v['fecha_entrega']); ?></small><?php endif; ?></td><td><?php echo e($v['productos']); ?><?php if($v['notas']): ?><br><small>Nota: <?php echo e($v['notas']); ?></small><?php endif; ?></td><td><form method="post" class="form-estado"><input type="hidden" name="id_venta" value="<?php echo $v['id_venta']; ?>"><select class="form-select form-select-sm" name="estado"><?php foreach($estadosPermitidos as $estado): ?><option value="<?php echo $estado; ?>" <?php echo $v['estado']===$estado?'selected':''; ?>><?php echo e(etiquetaEstadoPedido($estado)); ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-secondary" type="submit">Guardar</button></form></td><td>$<?php echo number_format($v['total'],2); ?></td></tr><?php endwhile; ?></tbody></table></div></main><?php require_once __DIR__.'/../php/pie.php'; ?>
